1: import RAPIER from '@dimforge/rapier3d-compat';
2: import type { GolfBallPhysics } from '../physics/GolfBallPhysics';
3: import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
4: import type { PhysicsWorld } from '../physics/PhysicsWorld';
5: import type { BumperConfig } from './types';
6: import { enterOnce } from './utils';
7: 
8: export class Bumper {
9:   readonly collider: RAPIER.Collider;
10:   readonly trigger: RAPIER.Collider;
11:   private readonly activeBodies = new Set<number>();
12: 
13:   constructor(physics: PhysicsWorld, readonly config: BumperConfig) {
14:     const obstacleGroups = collisionGroups(CollisionLayers.OBSTACLE, CollisionLayers.BALL);
15:     const sensorGroups = collisionGroups(CollisionLayers.SENSOR, CollisionLayers.BALL);
16:     this.collider = physics.world.createCollider(
17:       RAPIER.ColliderDesc.cylinder(config.halfHeight, config.radius)
18:         .setTranslation(config.position.x, config.position.y, config.position.z)
19:         .setRestitution(config.restitution ?? 0.9)
20:         .setCollisionGroups(obstacleGroups),
21:     );
22:     this.trigger = physics.world.createCollider(
23:       RAPIER.ColliderDesc.cylinder(config.halfHeight, config.radius + (config.triggerPadding ?? 0.3))
24:         .setTranslation(config.position.x, config.position.y, config.position.z)
25:         .setSensor(true)
26:         .setCollisionGroups(sensorGroups),
27:     );
28:   }
29: 
30:   update(ball: GolfBallPhysics): boolean {
31:     const p = ball.position;
32:     const dx = p.x - this.config.position.x;
33:     const dz = p.z - this.config.position.z;
34:     const radius = this.config.radius + (this.config.triggerPadding ?? 0.3);
35:     const inside = Math.hypot(dx, dz) <= radius
36:       && Math.abs(p.y - this.config.position.y) <= this.config.halfHeight + 0.5;
37:     if (!enterOnce(this.activeBodies, ball, inside)) return false;
38: 
39:     const length = Math.hypot(dx, dz);
40:     const x = length > 1e-8 ? dx / length : 1;
41:     const z = length > 1e-8 ? dz / length : 0;
42:     ball.body.wakeUp();
43:     ball.body.applyImpulse({ x: x * this.config.impulse, y: 0, z: z * this.config.impulse }, true);
44:     return true;
45:   }
46: }
